self, header: Iterable[str], row: Iterable[str], /
) -> Iterator[tuple[str, Any]]:
map_tf = {"true": True, "false": False}
for col, value in zip(header, row):
if col.startswith(("is_", "has_")):
yield col, map_tf[value]
elif col == "bytes":
yield col, int(value)
else:
yield col, value

