() -> Iterator[type[Any]]
Breadth-first sequence of all classes which inherit from cls.
def _subclasses(cls: type[Any]) -> Iterator[type[Any]]:
"""Breadth-first sequence of all classes which inherit from cls."""
seen = {cls}
current_set = {cls}
while current_set:
next_set = set()
for base in current_set:
for sub in base.__subclasses__():
if sub not in seen:
yield sub
seen.add(sub)
next_set.add(sub)
current_set = next_set

